          self.onmessage = function(e) {
            const { imageData, targetCount } = e.data;
            const { data, width, height } = imageData;
            const pixelCount = width * height;

            // 1. Characterize background boundaries
            const cornerIndices = [0, (width - 1) * 4, (width * (height - 1)) * 4, (width * height - 1) * 4];
            let bgR = 0, bgG = 0, bgB = 0;
            for (let i = 0; i < 4; i++) {
              const idx = cornerIndices[i];
              bgR += data[idx];
              bgG += data[idx + 1];
              bgB += data[idx + 2];
            }
            bgR /= 4.0; bgG /= 4.0; bgB /= 4.0;

            // 2. Identify portrait boundary thresholds
            const validIndices = new Int32Array(pixelCount);
            let validCount = 0;

            for (let i = 0; i < pixelCount; i++) {
              const idx = i * 4;
              if (data[idx + 3] < 30) continue;

              const r = data[idx];
              const g = data[idx + 1];
              const b = data[idx + 2];

              const distToBg = Math.sqrt((r-bgR)*(r-bgR) + (g-bgG)*(g-bgG) + (b-bgB)*(b-bgB)) / 255.0;
              if (distToBg < 0.12) continue;

              const lum = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0;
              if (lum <= 0.02) continue;

              const px = i % width;
              const py = (i / width) | 0;
              const edgeDistX = Math.min(px, width - px) / width;
              const edgeDistY = Math.min(py, height - py) / height;
              const edgeFactor = Math.min(1.0, edgeDistX * 18.0) * Math.min(1.0, edgeDistY * 18.0);

              if (Math.random() < edgeFactor) {
                validIndices[validCount++] = i;
              }
            }

            if (validCount === 0) {
              for (let i = 0; i < pixelCount; i++) validIndices[validCount++] = i;
            }

            // 3. Partition buffers for Volumetric Multi-Layers
            const bgCount = Math.floor(targetCount * 0.12);
            const fgCount = Math.floor(targetCount * 0.08);
            const portraitCount = targetCount - bgCount - fgCount;

            const targetPos = new Float32Array(targetCount * 3);
            const colors = new Float32Array(targetCount * 3);
            const randoms = new Float32Array(targetCount);
            const densityBoost = new Float32Array(targetCount);
            const startOffsets = new Float32Array(targetCount * 3);
            const layerInfo = new Float32Array(targetCount * 3);

            // Layer A: Portrait Particles (80% of payload)
            for (let i = 0; i < portraitCount; i++) {
              const rIndex = validIndices[Math.floor(Math.random() * validCount)];
              const px = rIndex % width;
              const py = (rIndex / width) | 0;

              const dataIdx = rIndex * 4;
              const r = data[dataIdx];
              const g = data[dataIdx + 1];
              const b = data[dataIdx + 2];
              const lum = (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0;

              const xCoord = (px / width - 0.5) * 50.0;
              const yCoord = -(py / height - 0.5) * 50.0;
              const zCoord = (lum - 0.5) * 5.0;

              const tIdx = i * 3;
              targetPos[tIdx] = xCoord + (Math.random() - 0.5) * 0.04;
              targetPos[tIdx + 1] = yCoord + (Math.random() - 0.5) * 0.04;
              targetPos[tIdx + 2] = zCoord + (Math.random() - 0.5) * 0.15;

              colors[tIdx] = r / 255.0;
              colors[tIdx + 1] = g / 255.0;
              colors[tIdx + 2] = b / 255.0;

              randoms[i] = Math.random();

              // High-pass edge contrast assessment
              const leftIdx = Math.max(0, px - 1) + py * width;
              const rightIdx = Math.min(width - 1, px + 1) + py * width;
              const topIdx = px + Math.max(0, py - 1) * width;
              const botIdx = px + Math.min(height - 1, py + 1) * width;

              const lumL = (0.2126 * data[leftIdx * 4] + 0.7152 * data[leftIdx * 4 + 1] + 0.0722 * data[leftIdx * 4 + 2]) / 255.0;
              const lumR = (0.2126 * data[rightIdx * 4] + 0.7152 * data[rightIdx * 4 + 1] + 0.0722 * data[rightIdx * 4 + 2]) / 255.0;
              const lumT = (0.2126 * data[topIdx * 4] + 0.7152 * data[topIdx * 4 + 1] + 0.0722 * data[topIdx * 4 + 2]) / 255.0;
              const lumB = (0.2126 * data[botIdx * 4] + 0.7152 * data[botIdx * 4 + 1] + 0.0722 * data[botIdx * 4 + 2]) / 255.0;

              const gradX = lumR - lumL;
              const gradY = lumB - lumT;
              const gradMag = Math.sqrt(gradX * gradX + gradY * gradY);

              densityBoost[i] = Math.min(1.0, gradMag * 4.0);

              // Initialize galaxy 5-arm spiral mapping offsets
              const galRadius = Math.pow(Math.random(), 0.6) * 120.0;
              const numArms = 5.0;
              const armOffset = Math.floor(Math.random() * numArms) * ((Math.PI * 2.0) / numArms);
              const twist = galRadius * 0.15;
              const theta = armOffset + twist + (Math.random() - 0.5) * 0.5;
              const galHeight = (Math.random() - 0.5) * 20.0 * Math.exp(-galRadius * 0.03);

              startOffsets[tIdx] = Math.cos(theta) * galRadius - targetPos[tIdx];
              startOffsets[tIdx + 1] = galHeight - targetPos[tIdx + 1];
              startOffsets[tIdx + 2] = Math.sin(theta) * galRadius - targetPos[tIdx + 2];

              layerInfo[tIdx] = 0.0; // Portrait tag
              layerInfo[tIdx + 1] = 0.85 + Math.random() * 0.5;
              layerInfo[tIdx + 2] = 0.5 + Math.random() * 1.0;

              if (i % 30000 === 0) {
                self.postMessage({ type: 'progress', value: (i / targetCount) * 0.8 });
              }
            }

            // Layer B: Foreground Floating dust elements (8% of payload)
            for (let i = 0; i < fgCount; i++) {
              const idx = portraitCount + i;
              const tIdx = idx * 3;

              targetPos[tIdx] = (Math.random() - 0.5) * 80.0;
              targetPos[tIdx + 1] = (Math.random() - 0.5) * 60.0;
              targetPos[tIdx + 2] = 10.0 + Math.random() * 80.0;

              colors[tIdx] = 1.0;
              colors[tIdx + 1] = 0.85 + Math.random() * 0.15;
              colors[tIdx + 2] = 0.6 + Math.random() * 0.2;

              randoms[idx] = Math.random();
              densityBoost[idx] = 0.0;
              startOffsets[tIdx] = 0; startOffsets[tIdx + 1] = 0; startOffsets[tIdx + 2] = 0;

              layerInfo[tIdx] = 1.0; // Foreground tag
              layerInfo[tIdx + 1] = 1.8 + Math.random() * 1.5;
              layerInfo[tIdx + 2] = 1.2 + Math.random() * 1.0;
            }

            // Layer C: Background Nebula Stars (12% of payload)
            for (let i = 0; i < bgCount; i++) {
              const idx = portraitCount + fgCount + i;
              const tIdx = idx * 3;

              const radius = 120.0 + Math.random() * 100.0;
              const theta = Math.random() * Math.PI * 2;
              const height = (Math.random() - 0.5) * 60.0;

              targetPos[tIdx] = Math.cos(theta) * radius;
              targetPos[tIdx + 1] = height;
              targetPos[tIdx + 2] = Math.sin(theta) * radius;

              colors[tIdx] = 0.15 + Math.random() * 0.15;
              colors[tIdx + 1] = 0.35 + Math.random() * 0.25;
              colors[tIdx + 2] = 0.55 + Math.random() * 0.35;

              randoms[idx] = Math.random();
              densityBoost[idx] = 0.0;
              startOffsets[tIdx] = 0; startOffsets[tIdx + 1] = 0; startOffsets[tIdx + 2] = 0;

              layerInfo[tIdx] = 2.0; // Background tag
              layerInfo[tIdx + 1] = 0.4 + Math.random() * 0.8;
              layerInfo[tIdx + 2] = 0.1 + Math.random() * 0.2;
            }

            self.postMessage({
              type: 'complete',
              data: { targetPos, colors, randoms, densityBoost, startOffsets, layerInfo }
            }, [targetPos.buffer, colors.buffer, randoms.buffer, densityBoost.buffer, startOffsets.buffer, layerInfo.buffer]);
          };
